<?php
declare(strict_types=1);

function inventory_ops_number(string $prefix,array $rows): string
{
    return $prefix.'-'.date('Y').'-'.str_pad((string)(count($rows)+1),4,'0',STR_PAD_LEFT);
}

function inventory_ops_default_company_id(): int
{
    if(current_company_id()!=='enterprise')return (int)current_company_id();$user=current_user();$allowed=permitted_company_ids($user);$primary=(int)($user['primary_company_id']??0);return in_array($primary,$allowed,true)?$primary:(int)($allowed[0]??0);
}

function inventory_ops_location_company(int $locationId): int
{
    $location=inventory_ops_find_location($locationId);return (int)($location['company_id']??0);
}

function inventory_ops_open_po_quantity(int $companyId,int $itemId): float
{
    $orders=[];foreach(data_collection('purchase_orders') as $po)$orders[(int)$po['id']]=$po;$qty=0.0;foreach(data_collection('purchase_order_lines') as $line){if((int)($line['item_id']??0)!==$itemId)continue;$po=$orders[(int)($line['purchase_order_id']??0)]??null;if(!$po||(int)($po['company_id']??0)!==$companyId||!in_array((string)($po['status']??''),['open','past_due','partially_received'],true))continue;$ordered=(float)($line['quantity_ordered']??$line['quantity']??0);$received=(float)($line['quantity_received']??0);$qty+=max(0,$ordered-$received);}return $qty;
}

function inventory_ops_forecast_quantity(int $companyId,int $itemId): float
{
    $item=data_find('items',$itemId);$categoryId=(int)($item['category_id']??0);$total=0.0;if(function_exists('demand_forecasts'))foreach(demand_forecasts() as $forecast){if((int)($forecast['company_id']??0)!==$companyId)continue;if((int)($forecast['category_id']??0)>0&&(int)$forecast['category_id']!==$categoryId)continue;if(!in_array((string)($forecast['status']??'active'),['active','approved'],true))continue;$total+=(float)($forecast['forecast_quantity']??0);}return $total;
}

function inventory_ops_transfer_source(int $destinationCompanyId,int $itemId,float $needed): ?array
{
    $best=null;foreach(inventory_ops_positions() as $position){if((int)$position['item_id']!==$itemId||(int)$position['company_id']===$destinationCompanyId)continue;$surplus=max(0,(float)$position['available']);if($surplus<=0)continue;$candidate=array_replace($position,['transfer_quantity'=>min($needed,$surplus)]);if(!$best||(float)$candidate['transfer_quantity']>(float)$best['transfer_quantity'])$best=$candidate;}return $best;
}

function inventory_ops_policy_blueprint(array $policy): array
{
    $position=inventory_ops_find_position((int)$policy['inventory_location_id'],(int)$policy['item_id'])??['quantity_on_hand'=>0,'quantity_allocated'=>0,'available'=>0,'unit_cost'=>(float)(data_find('items',(int)$policy['item_id'])['standard_cost']??0)];$companyId=(int)$policy['company_id'];$itemId=(int)$policy['item_id'];$available=(float)$position['available'];$allocated=(float)$position['quantity_allocated'];$openPo=inventory_ops_open_po_quantity($companyId,$itemId);$forecast=inventory_ops_forecast_quantity($companyId,$itemId);$target=max((float)$policy['reorder_point'],(float)$policy['minimum_quantity'])+(float)$policy['safety_stock']+$forecast;$needed=max(0,$target-$available-$openPo);$maximum=(float)$policy['maximum_quantity'];if($maximum>0)$needed=min($needed,max(0,$maximum-$available-$openPo));$source=$needed>0?inventory_ops_transfer_source($companyId,$itemId,$needed):null;$type=$needed<=0?'hold':($source&&$source['transfer_quantity']>0?'transfer':'purchase');$quantity=$type==='transfer'?(float)$source['transfer_quantity']:$needed;$unitCost=(float)($position['unit_cost']?:data_find('items',$itemId)['standard_cost']??0);$score=100;if($available<(float)$policy['safety_stock'])$score-=25;if($openPo<=0&&$needed>0)$score-=15;if($type==='purchase'&&empty($policy['preferred_supplier_id']))$score-=20;if($forecast<=0)$score-=10;return ['position'=>$position,'available_quantity'=>$available,'allocated_quantity'=>$allocated,'open_po_quantity'=>$openPo,'forecast_quantity'=>$forecast,'safety_stock_quantity'=>(float)$policy['safety_stock'],'recommended_quantity'=>round($quantity,4),'estimated_unit_cost'=>$unitCost,'estimated_value'=>round($quantity*$unitCost,2),'recommendation_type'=>$type,'source_inventory_location_id'=>$source['inventory_location_id']??null,'required_date'=>date('Y-m-d',strtotime('+'.max(1,(int)$policy['lead_time_days']).' days')),'readiness_score'=>max(0,$score),'evidence_note'=>match($type){'hold'=>'Available inventory and open purchase orders cover the policy target, forecast, and safety stock.','transfer'=>'A permitted internal location can cover all or part of the requirement before new purchasing.','purchase'=>'No supported internal surplus covers the policy requirement; a governed purchase request is recommended.',default=>'No action.'}];
}

function inventory_ops_generate_recommendation(array $policy): array
