    $blueprint=inventory_ops_policy_blueprint($policy);$record=array_replace($blueprint,['id'=>null,'recommendation_number'=>inventory_ops_number('REC-INV',inventory_ops_recommendations()),'policy_id'=>(int)$policy['id'],'company_id'=>(int)$policy['company_id'],'inventory_location_id'=>(int)$policy['inventory_location_id'],'item_id'=>(int)$policy['item_id'],'preferred_supplier_id'=>$policy['preferred_supplier_id']??null,'status'=>'draft','approval_id'=>null,'converted_request_id'=>null,'converted_transfer_id'=>null,'created_by'=>(int)current_user()['id']]);unset($record['position'],$record['readiness_score']);$saved=inventory_ops_save_recommendation($record);inventory_ops_add_event((int)$saved['company_id'],(int)$saved['inventory_location_id'],(int)$saved['item_id'],'replenishment_recommendation',(int)$saved['id'],'recommendation_generated',null,'draft',$saved['estimated_value']>=25000?'high':'medium',(float)$saved['recommended_quantity'],(float)$saved['estimated_value'],$saved['evidence_note']);return $saved;
