function inventory_ops_recommendation_effective_status(array $recommendation): string
{
    $stored=(string)($recommendation['status']??'draft');if(in_array($stored,['converted','dismissed'],true))return $stored;$approvalId=(int)($recommendation['approval_id']??0);if($approvalId>0){$approval=data_find('workflow_approvals',$approvalId);if($approval&&in_array((string)($approval['status']??''),['pending','in_review','approved','changes_requested','rejected'],true))return (string)$approval['status'];}return $stored;
}

function inventory_ops_submit_recommendation(array $recommendation): array
{
    if(!in_array(inventory_ops_recommendation_effective_status($recommendation),['draft','changes_requested'],true))throw new RuntimeException('This recommendation is already routed or closed.');$policy=inventory_ops_find_policy((int)$recommendation['policy_id']);$reviewerId=(int)($policy['reviewer_id']??6);$approval=data_upsert('workflow_approvals',['id'=>null,'company_id'=>$recommendation['company_id'],'module'=>'inventory','entity_type'=>'inventory_replenishment_recommendation','entity_id'=>$recommendation['id'],'title'=>$recommendation['recommendation_number'].' · '.money((float)$recommendation['estimated_value']),'submitted_by'=>(int)current_user()['id'],'assigned_to'=>$reviewerId,'status'=>'pending','submitted_at'=>date('Y-m-d H:i:s'),'due_date'=>date('Y-m-d',strtotime('+3 days')),'notes'=>'Review on-hand, allocations, reservations, open PO coverage, forecasts, transfer opportunity, supplier, lead time, safety stock, quantity, and value evidence.']);$before=$recommendation['status'];$recommendation['approval_id']=(int)$approval['id'];$recommendation['status']='submitted';$saved=inventory_ops_save_recommendation($recommendation);inventory_ops_add_event((int)$saved['company_id'],(int)$saved['inventory_location_id'],(int)$saved['item_id'],'replenishment_recommendation',(int)$saved['id'],'submitted',$before,'submitted','medium',(float)$saved['recommended_quantity'],(float)$saved['estimated_value'],'Recommendation routed for human approval.');inventory_ops_notify($reviewerId,(int)$saved['company_id'],'Inventory recommendation awaiting approval',$saved['recommendation_number'].' requests '.number_format((float)$saved['recommended_quantity'],2).' units.','warning');return $saved;
}

function inventory_ops_convert_recommendation(array $recommendation): array
