    if($recommendation['recommendation_type']==='transfer'){$sourceLocation=inventory_ops_find_location((int)$recommendation['source_inventory_location_id']);$destination=inventory_ops_find_location((int)$recommendation['inventory_location_id']);if(!$sourceLocation||!$destination)throw new RuntimeException('Transfer locations are unavailable.');$transfer=inventory_ops_save_transfer(['id'=>null,'transfer_number'=>inventory_ops_number('TRF-INV',inventory_ops_transfers()),'source_company_id'=>$sourceLocation['company_id'],'destination_company_id'=>$destination['company_id'],'source_inventory_location_id'=>$sourceLocation['id'],'destination_inventory_location_id'=>$destination['id'],'project_workorder_id'=>null,'status'=>'draft','required_date'=>$recommendation['required_date'],'shipped_at'=>null,'received_at'=>null,'carrier'=>'','tracking_number'=>'','freight_cost'=>0,'owner_id'=>(int)current_user()['id'],'reviewer_id'=>6,'approval_id'=>null,'evidence_note'=>'Created from approved '.$recommendation['recommendation_number'].'. '.$recommendation['evidence_note']]);inventory_ops_save_transfer_line(['id'=>null,'transfer_request_id'=>$transfer['id'],'item_id'=>$recommendation['item_id'],'quantity_requested'=>$recommendation['recommended_quantity'],'quantity_shipped'=>0,'quantity_received'=>0,'unit_cost'=>$recommendation['estimated_unit_cost'],'serial_or_lot_reference'=>'','condition_status'=>'pending','notes'=>'Approved replenishment recommendation transfer line.']);inventory_ops_add_transfer_event((int)$transfer['id'],'transfer_created',null,'draft','medium','Transfer created from approved replenishment recommendation.');$reference=(int)$transfer['id'];$kind='transfer';}
